/* ============================================================
   V6 EXTERNAL EVIDENCE LAYER
   This is intentionally separate from Bangladesh FCT nutrient data.
   Public/peer-reviewed sources are summarized conservatively.
   ============================================================ */
const EXT_SOURCES = {
  gi: {name:"University of Sydney GI Database / International GI Tables 2021", url:"https://glycemicindex.com/gi-search/"},
  fodmap: {name:"Monash University FODMAP public food guidance", url:"https://www.monashfodmap.com/about-fodmap-and-ibs/high-and-low-fodmap-foods/"},
  gluten: {name:"NIDDK - Celiac disease: gluten-containing grains", url:"https://www.niddk.nih.gov/health-information/digestive-diseases/celiac-disease/eating-diet-nutrition"},
  purine: {name:"USDA/NIH purine composition study (2025)", url:"https://pubmed.ncbi.nlm.nih.gov/41173372/"},
  oxalate: {name:"Oxalate content of food: a tangled web (Urology 2014)", url:"https://pubmed.ncbi.nlm.nih.gov/25168533/"},
  histamine: {name:"Histamine intolerance and dietary management review (2016)", url:"https://pubmed.ncbi.nlm.nih.gov/27590961/"},
  nightshade: {name:"Botanical food-family identity rule", url:""}
};
 
function extText(f){ return searchHay(f); }
function extHas(h, arr){ return arr.some(x=>h.includes(norm(x))); }
 
function externalProfile(f){
  const h=extText(f);
  const out={
    gi:{status:"Data unavailable",value:null,className:"",note:"No sufficiently close tested match assigned.",source:EXT_SOURCES.gi},
    fodmap:{status:"Not mapped",className:"",note:"Serving size matters; public Monash examples only are mapped.",source:EXT_SOURCES.fodmap},
    gluten:{status:"Not identified",className:"neutral",note:"Ingredient list/cross-contact may still matter for processed foods.",source:EXT_SOURCES.gluten},
    nightshade:{status:"No",className:"neutral",note:"Identity tag only; not an automatic inflammation warning.",source:EXT_SOURCES.nightshade},
    purine:{status:"No exact value",className:"",note:"Category-level reference only unless an exact analytical match is available.",source:EXT_SOURCES.purine},
    oxalate:{status:"No verified match",className:"",note:"Published values can vary substantially by method/source.",source:EXT_SOURCES.oxalate},
    histamine:{status:"Uncertain/variable",className:"",note:"There is no homogeneous consensus; freshness, storage and processing can materially change amine levels.",source:EXT_SOURCES.histamine}
  };
 
  // Gluten: NIDDK identifies wheat, barley, rye and triticale as gluten-containing grains.
  if(extHas(h,["wheat","গম","barley","যব","rye","triticale","semolina","durum","spelt","malt"])) {
    out.gluten={status:"Contains / likely contains gluten",className:"high",note:"Wheat/barley/rye/triticale or a named derivative detected. Processed foods still require label review.",source:EXT_SOURCES.gluten};
  } else if(extHas(h,["rice","চাল","ভাত","maize","corn","ভুট্টা","potato","আলু","egg","ডিম","milk","দুধ","fish","মাছ","meat","chicken","fruit","orange","banana","pineapple"])) {
    out.gluten={status:"Naturally gluten-free identity",className:"low",note:"Cross-contact/added ingredients are not assessed by this identity rule.",source:EXT_SOURCES.gluten};
  }
 
  // Nightshade identity: tomato, potato, eggplant/brinjal and peppers/chillies.
  if(extHas(h,["tomato","টমেটো","potato","আলু","brinjal","eggplant","aubergine","বেগুন","chilli","chili","pepper","capsicum","মরিচ"])) {
    out.nightshade={status:"Yes",className:"info",note:"Nightshade/Solanaceae identity tag; individual tolerance varies.",source:EXT_SOURCES.nightshade};
  }
 
  // Public Monash examples. These are serve-dependent; the UI deliberately avoids pretending a universal gram cut-off.
  const fodLow=["eggplant","aubergine","green bean","bok choy","green capsicum","carrot","cucumber","lettuce","potato","orange","pineapple","kiwi","mandarin","blueberry","peanut","pumpkin seed","walnut","egg","firm tofu","tempeh"];
  const fodHigh=["artichoke","asparagus","garlic","green pea","leek","mushroom","onion","red capsicum","apple","cherry","dried fruit","mango","nectarine","peach","pear","plum","watermelon","cashew","pistachio","honey"];
  if(extHas(h,fodLow)) out.fodmap={status:"Low FODMAP example",className:"low",note:"Monash public guidance lists this food/type as a low-FODMAP option; rating remains serving-dependent.",source:EXT_SOURCES.fodmap};
  if(extHas(h,fodHigh)) out.fodmap={status:"High FODMAP example",className:"high",note:"Monash public guidance lists this food/type among high-FODMAP examples; serving and preparation still matter.",source:EXT_SOURCES.fodmap};
  if(f.code.slice(0,2)==="02" && out.fodmap.status==="Not mapped") out.fodmap={status:"Often higher FODMAP",className:"warn",note:"Monash public guidance notes most legumes/pulses can be high FODMAP; serving and preparation matter.",source:EXT_SOURCES.fodmap};
  if(f.code.slice(0,2)==="09" || f.code.slice(0,2)==="10" || f.code.slice(0,2)==="11") {
    if(!/marinated|processed|sausage/.test(h)) out.fodmap={status:"Typically low FODMAP when plain",className:"low",note:"Plain cooked meat, poultry, seafood and eggs are listed as low-FODMAP protein options; sauces/marinades can change this.",source:EXT_SOURCES.fodmap};
  }
  if(f.code.slice(0,2)==="12" && extHas(h,["milk","yoghurt","yogurt","custard","ice cream","condensed milk"])) out.fodmap={status:"Potentially high FODMAP (lactose)",className:"warn",note:"Monash public guidance lists conventional cow milk/yoghurt and several milk products among high-FODMAP examples.",source:EXT_SOURCES.fodmap};
 
  // GI: exact/public tested examples or broad evidence only. GI varies with variety, processing and cooking.
  if(/bread, white|white bread/.test(h)) out.gi={status:"GI 75",value:75,className:"High",note:"Representative tested white-bread entry in the University of Sydney GI database. Brand/process can differ.",source:EXT_SOURCES.gi};
  else if(/full-fat.*milk|milk.*full-fat|milk, cow|cow.*milk/.test(h)) out.gi={status:"GI about 30",value:30,className:"Low",note:"Representative full-fat milk entry in the University of Sydney GI database.",source:EXT_SOURCES.gi};
  else if(/brown rice/.test(h)) out.gi={status:"GI about 59 (representative)",value:59,className:"Medium",note:"A medium-grain brown-rice entry in the Sydney GI database is GI 59; rice GI varies by variety and cooking.",source:EXT_SOURCES.gi};
  else if(/jasmine.*rice|rice.*jasmine/.test(h)) out.gi={status:"GI often high in tested jasmine rice",value:null,className:"High/variable",note:"Sydney database contains multiple jasmine-rice entries in the high range; exact value depends on product and preparation.",source:EXT_SOURCES.gi};
  else if(/white rice|rice, white|চাল|ভাত/.test(h)) out.gi={status:"Variable",value:null,className:"Low-to-high depending on variety/process",note:"International tables show wide GI variation among rice products; no single GI should be assigned to a generic Bangladesh rice entry.",source:EXT_SOURCES.gi};
  else if(f.code.slice(0,2)==="02") out.gi={status:"Usually low-GI food group",value:null,className:"Usually low",note:"The 2021 International GI Tables report legumes are usually low-GI, but an exact value is not assigned without a close tested match.",source:EXT_SOURCES.gi};
  else if(f.code.slice(0,2)==="08") out.gi={status:"Often low-GI food group",value:null,className:"Often low",note:"The 2021 International GI Tables report fruits are usually low-GI, but individual foods vary.",source:EXT_SOURCES.gi};
  else if(/potato|আলু/.test(h)) out.gi={status:"Often high / variety-dependent",value:null,className:"Often high",note:"The 2021 International GI Tables report most potato varieties are high GI, with some lower-GI varieties identified.",source:EXT_SOURCES.gi};
 
  // Purine: USDA 2025 category ranges, displayed as reference ranges rather than fake food-specific values.
  if(f.code.slice(0,2)==="09" || f.code.slice(0,2)==="10") out.purine={status:"Category reference: 96-448 mg/100g",className:"moderate-high",note:"USDA/NIH 2025 measured meat and seafood samples across this range; this is not an exact value for this Bangladesh food.",source:EXT_SOURCES.purine};
  else if(f.code.slice(0,2)==="02" || f.code.slice(0,2)==="03" || f.code.slice(0,2)==="04" || f.code.slice(0,2)==="05") out.purine={status:"Category reference: 9-72 mg/100g",className:"lower",note:"USDA/NIH 2025 measured legumes and vegetables across this range; individual foods differ.",source:EXT_SOURCES.purine};
  else if(f.code.slice(0,2)==="11" || f.code.slice(0,2)==="12") out.purine={status:"Negligible in study categories",className:"low",note:"USDA/NIH 2025 reported negligible purines in milk, yoghurt, cheeses and eggs.",source:EXT_SOURCES.purine};
 
  // Oxalate: only ranges explicitly reported in the 2014 review are mapped.
  if(extHas(h,["spinach","পালং"])) out.oxalate={status:"Published range: 364-1145 mg/100g",className:"high/variable",note:"Large between-source variability was reported; use this as a cautionary range, not a single fixed value.",source:EXT_SOURCES.oxalate};
  else if(extHas(h,["orange","কমলা"])) out.oxalate={status:"Published range: 2.07-10.64 mg/100g",className:"variable",note:"Range reported across reviewed sources.",source:EXT_SOURCES.oxalate};
  else if(extHas(h,["banana","কলা"])) out.oxalate={status:"Published range: 0-9.9 mg/100g",className:"variable",note:"Range reported across reviewed sources.",source:EXT_SOURCES.oxalate};
  else if(extHas(h,["peanut","groundnut","china badam","চিনাবাদাম"])) out.oxalate={status:"Published range: 64.57-348.58 mg/100g",className:"highly variable",note:"Large between-source variability was reported for peanuts.",source:EXT_SOURCES.oxalate};
 
  // Histamine: no universal quantitative table is presented as authoritative. Flag foods where storage/fermentation deserves extra attention.
  if(extHas(h,["fermented","pickle","yogurt","yoghurt","cheese","dried fish","smoked fish","canned fish","sardine","mackerel","tuna","shrimp paste","fish sauce"])) {
    out.histamine={status:"Potential concern / highly variable",className:"warn",note:"Histamine/biogenic amine levels can vary markedly with fermentation, storage, freshness and processing; published sources lack homogeneous consensus.",source:EXT_SOURCES.histamine};
  }
 
  return out;
}
 
function externalBadges(f,limit=3){
  const x=externalProfile(f), b=[];
  if(x.gi.className) b.push({k:"gi",i:"📈",t:`GI ${x.gi.className}`});
  if(x.fodmap.className) b.push({k:"fodmap",i:"🫘",t:`FODMAP ${x.fodmap.className}`});
  if(x.gluten.className==="high") b.push({k:"gluten",i:"🌾",t:"GLUTEN"});
  if(x.nightshade.status==="Yes") b.push({k:"nightshade",i:"🌙",t:"NIGHTSHADE"});
  return b.slice(0,limit);
}
 
