  bindSearch(); bindFoodGrid();
  document.getElementById("bdCategory").onchange=e=>{state.category=e.target.value;state.page=1;render();};
  document.getElementById("bdSort").onchange=e=>{state.sort=e.target.value;state.page=1;render();};
  document.getElementById("bdLens").onchange=e=>{state.healthLens=e.target.value;render();};
  document.getElementById("bdFavOnly").onclick=()=>{state.favoritesOnly=!state.favoritesOnly;state.page=1;render();};
