function closeModal(){document.getElementById("bdModal")?.classList.remove("open");}
 
function openPlate(){
  const d=document.getElementById("bdDrawer"), box=document.getElementById("bdDrawerBox");
  box.innerHTML=plateHTML(); d.classList.add("open"); bindPlate();
}
function plateHTML(){
  const totals=plateTotals();
  return `<div class="bd-drawerhead"><div><small>MY PLATE</small><h2>আপনার প্লেট</h2></div><button data-close-drawer>×</button></div>
  ${plate.length?`<div class="bd-plateitems">${plate.map(x=>{const f=FOODS.find(z=>z.code===x.code);return `<div><span>${f?.icon||"🍴"}</span><div><b>${esc(nameBn(f)||x.code)}</b><small>${fmt(gramsValue(f?.energy_kcal,x.grams),0)} kcal</small></div><input data-qty="${x.code}" type="number" min="1" max="3000" value="${x.grams}"><span>g</span><button data-remove="${x.code}">×</button></div>`}).join("")}</div>
  <h3>Plate Total</h3>${totalsGrid(totals)}
  ${plateCheckHTML(totals)}
  <h3>Food Contribution</h3>${contributionHTML("protein_g")}
  <div class="bd-platebuttons"><button id="bdClearPlate">Clear Plate</button><button id="bdPlateCsv">Export CSV</button><button id="bdPlateShare">▣ Facebook Card</button></div>`:
  `<div class="bd-empty">🍽️<h3>My Plate এখন খালি</h3><p>Food card থেকে + My Plate চাপুন।</p></div>`}`;
}
function plateTotals(){
  const t={}; NUTRIENTS.forEach(m=>t[m[0]]=0);
  plate.forEach(x=>{const f=FOODS.find(z=>z.code===x.code);if(!f)return;NUTRIENTS.forEach(m=>{const v=gramsValue(f[m[0]],x.grams);if(v!==null)t[m[0]]+=v;});});
  return t;
}
function totalsGrid(t){
  const ks=["energy_kcal","protein_g","fat_g","carb_g","fibre_g","calcium_mg","iron_mg","potassium_mg","sodium_mg","vitamin_c_mg"];
  return `<div class="bd-totalgrid">${ks.map(k=>{const m=NMAP[k];return `<div><span>${m[1]}</span><b>${fmt(t[k],k==="energy_kcal"?0:1)}</b><small>${m[2]}</small></div>`}).join("")}</div>`;
}
function plateCheckHTML(t){
  const notes=[];
  if((t.fibre_g||0)>=8) notes.push(["✓","ফাইবার ভালো মাত্রায় আছে","good"]);
  else notes.push(["○","ফাইবার আরও বাড়ানো যেতে পারে","neutral"]);
  if((t.sodium_mg||0)>=800) notes.push(["⚠","সোডিয়াম তুলনামূলক বেশি","warn"]);
  if((t.protein_g||0)>=20) notes.push(["✓","প্রোটিনের পরিমাণ উল্লেখযোগ্য","good"]);
  if((t.energy_kcal||0)>=800) notes.push(["⚠","মোট energy বেশি; meal context বিবেচনা করুন","warn"]);
  return `<div class="bd-platecheck"><h3>Quick Plate Check</h3>${notes.map(n=>`<div class="${n[2]}"><b>${n[0]}</b><span>${n[1]}</span></div>`).join("")}<small>এটি nutrient-based screening cue; ব্যক্তিগত medical advice নয়।</small></div>`;
}
 
function contributionHTML(key){
  const values=plate.map(x=>{const f=FOODS.find(z=>z.code===x.code);return {x,f,v:gramsValue(f?.[key],x.grams)||0}}), total=values.reduce((a,b)=>a+b.v,0);
  return `<div class="bd-contrib">${values.sort((a,b)=>b.v-a.v).map(o=>{const p=total?o.v/total*100:0;return `<div><span>${esc(nameBn(o.f)||o.x.code)}</span><div><i style="width:${Math.min(100,p)}%"></i></div><b>${Math.round(p)}%</b></div>`}).join("")}</div>`;
}
function bindPlate(){
  document.querySelectorAll("[data-qty]").forEach(i=>i.onchange=e=>{const x=plate.find(z=>z.code===e.target.dataset.qty);if(x)x.grams=Math.max(1,Number(e.target.value)||100);savePlate();openPlate();});
  document.querySelectorAll("[data-remove]").forEach(b=>b.onclick=()=>{plate=plate.filter(x=>x.code!==b.dataset.remove);savePlate();updateCounts();openPlate();});
  const c=document.getElementById("bdClearPlate"); if(c)c.onclick=()=>{plate=[];savePlate();updateCounts();openPlate();};
  const ex=document.getElementById("bdPlateCsv");if(ex)ex.onclick=exportPlateCSV;
  const sh=document.getElementById("bdPlateShare");if(sh)sh.onclick=downloadPlateShareCard;
}
function exportPlateCSV(){
  const rows=[["Food","Code","Grams","Calories","Protein_g","Carb_g","Fat_g","Fibre_g"]];
  plate.forEach(x=>{const f=FOODS.find(z=>z.code===x.code);rows.push([f?.english||"",x.code,x.grams,gramsValue(f?.energy_kcal,x.grams)||"",gramsValue(f?.protein_g,x.grams)||"",gramsValue(f?.carb_g,x.grams)||"",gramsValue(f?.fat_g,x.grams)||"",gramsValue(f?.fibre_g,x.grams)||""]);});
  downloadCSV(rows,"my-plate.csv");
}
function closeDrawer(){document.getElementById("bdDrawer")?.classList.remove("open");}
 
function openCompare(){
  if(state.compare.length<2){toast("Compare করতে অন্তত ২টি খাবার select করুন");return;}
  const fs=state.compare.map(c=>FOODS.find(f=>f.code===c)).filter(Boolean);
  const keys=["energy_kcal","protein_g","fat_g","carb_g","fibre_g","calcium_mg","iron_mg","potassium_mg","sodium_mg","vitamin_c_mg"];
  const box=document.getElementById("bdModalBox");
  box.innerHTML=`<div class="bd-modalhead"><span>⚖️</span><div><small>COMPARE</small><h2>Food Comparison</h2><p>প্রতি 100 g edible portion</p></div><button data-close-modal>×</button></div>
  <div class="bd-comparetable"><table><thead><tr><th>Nutrient</th>${fs.map(f=>`<th>${f.icon}<br>${esc(nameBn(f))}</th>`).join("")}</tr></thead><tbody>
  ${keys.map(k=>{const m=NMAP[k], vals=fs.map(f=>nval(f[k])); const max=Math.max(...vals.filter(v=>v!==null));return `<tr><td>${m[1]}<small>${m[2]}</small></td>${vals.map(v=>`<td class="${v!==null&&v===max?"max":""}">${v===null?"—":fmt(v)}</td>`).join("")}</tr>`}).join("")}
  </tbody></table></div>
  <div class="bd-comparefacts">${compareFacts(fs)}</div>
  <div class="bd-sharebar"><button id="bdCompareShare">▣ Download Facebook Card</button></div>
  <p class="bd-note">Highlighted cell শুধু ঐ nutrient-এর বেশি মান দেখায়; overall “best food” বোঝায় না।</p>`;
  document.getElementById("bdModal").classList.add("open");
  const sh=document.getElementById("bdCompareShare"); if(sh) sh.onclick=()=>downloadCompareShareCard(fs);
}
function compareFacts(fs){
  const facts=[];
  [["protein_g","প্রোটিন"],["fibre_g","ফাইবার"],["iron_mg","আয়রন"],["calcium_mg","ক্যালসিয়াম"]].forEach(([k,label])=>{
    const vals=fs.map(f=>({f,v:nval(f[k])})).filter(x=>x.v!==null).sort((a,b)=>b.v-a.v);
    if(vals.length) facts.push(`<div><b>${label} বেশি</b><span>${esc(nameBn(vals[0].f))} · ${fmt(vals[0].v)} ${NMAP[k][2]}</span></div>`);
  });
  const kc=fs.map(f=>({f,v:nval(f.energy_kcal)})).filter(x=>x.v!==null).sort((a,b)=>a.v-b.v);
  if(kc.length) facts.push(`<div><b>ক্যালরি কম</b><span>${esc(nameBn(kc[0].f))} · ${fmt(kc[0].v,0)} kcal</span></div>`);
  return facts.join("");
}
 
 
function roundedRect(ctx,x,y,w,h,r,fill,stroke){
  const rr=Math.min(r,w/2,h/2);ctx.beginPath();ctx.moveTo(x+rr,y);ctx.arcTo(x+w,y,x+w,y+h,rr);ctx.arcTo(x+w,y+h,x,y+h,rr);ctx.arcTo(x,y+h,x,y,rr);ctx.arcTo(x,y,x+w,y,rr);ctx.closePath();if(fill){ctx.fillStyle=fill;ctx.fill();}if(stroke){ctx.strokeStyle=stroke;ctx.stroke();}
}
function canvasBase(title,subtitle){
  const c=document.createElement("canvas");c.width=1080;c.height=1350;const x=c.getContext("2d");
  const g=x.createLinearGradient(0,0,1080,1350);g.addColorStop(0,"#07111f");g.addColorStop(.55,"#0c2135");g.addColorStop(1,"#081421");x.fillStyle=g;x.fillRect(0,0,1080,1350);
  x.fillStyle="rgba(50,224,196,.12)";x.beginPath();x.arc(950,120,270,0,Math.PI*2);x.fill();
  x.fillStyle="#32e0c4";x.font="700 34px Arial";x.fillText("SHUDDHO ACADEMY",70,85);
  x.fillStyle="#ffffff";x.font="800 58px Arial";wrapCanvasText(x,title,70,175,940,68,2);
  x.fillStyle="#9fb3c9";x.font="30px Arial";wrapCanvasText(x,subtitle||"",70,310,930,40,2);
  return [c,x];
}
function wrapCanvasText(ctx,text,x,y,maxWidth,lineHeight,maxLines=99){
  const words=String(text||"").split(/\s+/);let line="",lines=0;
  for(let n=0;n<words.length;n++){const test=line?line+" "+words[n]:words[n];if(ctx.measureText(test).width>maxWidth&&line){ctx.fillText(line,x,y+lines*lineHeight);lines++;line=words[n];if(lines>=maxLines)return;}else line=test;}
  if(line&&lines<maxLines)ctx.fillText(line,x,y+lines*lineHeight);
}
function metricBox(ctx,label,value,unit,x,y,w=285){
  roundedRect(ctx,x,y,w,125,24,"rgba(255,255,255,.055)","rgba(255,255,255,.10)");ctx.fillStyle="#9fb3c9";ctx.font="24px Arial";ctx.fillText(label,x+22,y+35);ctx.fillStyle="#fff";ctx.font="800 38px Arial";ctx.fillText(String(value),x+22,y+82);ctx.fillStyle="#32e0c4";ctx.font="22px Arial";ctx.fillText(unit,x+22,y+111);
}
function canvasFooter(ctx){
  ctx.strokeStyle="rgba(255,255,255,.14)";ctx.beginPath();ctx.moveTo(70,1215);ctx.lineTo(1010,1215);ctx.stroke();ctx.fillStyle="#d7e2ee";ctx.font="24px Arial";ctx.fillText("Source: Food Composition Table for Bangladesh (2013)",70,1265);ctx.fillStyle="#91a7bd";ctx.font="21px Arial";ctx.fillText("INFS, University of Dhaka • shuddhoacademy",70,1307);
}
function saveCanvas(c,name){c.toBlob(blob=>{if(!blob)return;const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500);},"image/png",1);}
function downloadFoodShareCard(f,g=100){
  const [c,x]=canvasBase(nameBn(f),nameEn(f));x.fillStyle="#32e0c4";x.font="700 24px Arial";x.fillText(`${g} g serving`,70,390);
  const vals=[
    ["Energy",fmt(gramsValue(f.energy_kcal,g),0),"kcal"],["Protein",fmt(gramsValue(f.protein_g,g)),"g"],["Carbohydrate",fmt(gramsValue(f.carb_g,g)),"g"],
    ["Fat",fmt(gramsValue(f.fat_g,g)),"g"],["Fibre",fmt(gramsValue(f.fibre_g,g)),"g"],["Iron",fmt(gramsValue(f.iron_mg,g)),"mg"],
    ["Calcium",fmt(gramsValue(f.calcium_mg,g),0),"mg"],["Potassium",fmt(gramsValue(f.potassium_mg,g),0),"mg"],["Vitamin C",fmt(gramsValue(f.vitamin_c_mg,g)),"mg"]
  ];
  vals.forEach((m,i)=>metricBox(x,m[0],m[1],m[2],70+(i%3)*315,450+Math.floor(i/3)*150,285));
  x.fillStyle="#fff";x.font="700 26px Arial";x.fillText("Nutrition values scaled from the source per-100 g data.",70,965);
  x.fillStyle="#9fb3c9";x.font="22px Arial";wrapCanvasText(x,"Clinical/functional tags require their own cited evidence and are not treated as Bangladesh FCT nutrient values.",70,1010,920,32,3);
  canvasFooter(x);saveCanvas(c,`shuddho-${f.code}-${g}g.png`);
}
function downloadPlateShareCard(){
  if(!plate.length){toast("My Plate খালি");return;}const t=plateTotals();const [c,x]=canvasBase("My Plate — পুষ্টি সারাংশ",`${plate.length}টি খাবার`);
  x.fillStyle="#b8c9d9";x.font="26px Arial";let yy=390;plate.slice(0,8).forEach(p=>{const f=FOODS.find(z=>z.code===p.code);x.fillText(`${nameBn(f)} — ${p.grams} g`,70,yy);yy+=38;});
  const vals=[["Energy",fmt(t.energy_kcal,0),"kcal"],["Protein",fmt(t.protein_g),"g"],["Carbohydrate",fmt(t.carb_g),"g"],["Fat",fmt(t.fat_g),"g"],["Fibre",fmt(t.fibre_g),"g"],["Iron",fmt(t.iron_mg),"mg"],["Calcium",fmt(t.calcium_mg,0),"mg"],["Potassium",fmt(t.potassium_mg,0),"mg"],["Sodium",fmt(t.sodium_mg,0),"mg"]];
  vals.forEach((m,i)=>metricBox(x,m[0],m[1],m[2],70+(i%3)*315,690+Math.floor(i/3)*150,285));canvasFooter(x);saveCanvas(c,"shuddho-my-plate.png");
}
function downloadCompareShareCard(fs){
  if(!fs||fs.length<2)return;const [c,x]=canvasBase("Food Comparison",fs.map(nameBn).join(" vs "));const keys=[["energy_kcal","Energy","kcal"],["protein_g","Protein","g"],["fibre_g","Fibre","g"],["iron_mg","Iron","mg"],["calcium_mg","Calcium","mg"],["potassium_mg","Potassium","mg"]];
  const cols=Math.min(fs.length,4),cw=900/cols;x.fillStyle="#32e0c4";x.font="700 22px Arial";fs.slice(0,4).forEach((f,i)=>{wrapCanvasText(x,nameBn(f),80+i*cw,400,cw-20,28,2);});
  keys.forEach((k,r)=>{const y=500+r*100;x.fillStyle="#9fb3c9";x.font="22px Arial";x.fillText(k[1],70,y);fs.slice(0,4).forEach((f,i)=>{x.fillStyle="#fff";x.font="800 28px Arial";x.fillText(`${fmt(f[k[0]])} ${k[2]}`,270+i*cw,y);});});canvasFooter(x);saveCanvas(c,"shuddho-food-compare.png");
}
 
function downloadCSV(rows,name){
  const csv=rows.map(r=>r.map(x=>`"${String(x??"").replace(/"/g,'""')}"`).join(",")).join("\n");
  const a=document.createElement("a"); a.href=URL.createObjectURL(new Blob(["\ufeff"+csv],{type:"text/csv;charset=utf-8"}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);
}
function toast(msg){const t=document.getElementById("bdToast");t.textContent=msg;t.classList.add("show");clearTimeout(t._x);t._x=setTimeout(()=>t.classList.remove("show"),2200);}
 
